import {templateBindingsFor,templateDigest,templateValueAt,type DocumentationTemplateKind,type TemplateContextObject,type TemplateContextValue} from "./template-contract.js";

export type RichEmphasis="strong"|"emphasis";
export type RichInline=({text:string}|{binding:string})&{emphasis?:RichEmphasis};
export type RichTemplateBlock=
  |{id:string;type:"heading";level:1|2|3;content:readonly RichInline[]}
  |{id:string;type:"paragraph";content:readonly RichInline[]}
  |{id:string;type:"divider"}
  |{id:string;type:"theme-logo"}
  |{id:string;type:"page-visual";source:string}
  |{id:string;type:"data-table";source:"table"|"overview.fields"|"flow.rows"|"matrix.rows"|"profile.rows"}
  |{id:string;type:"concept-group";source:string}
  |{id:string;type:"repeat";items:string;variable:string;children:readonly RichTemplateBlock[]};
export interface RichDocumentationTemplate {id:string;name:string;format:"rich";kind:DocumentationTemplateKind;contractVersion:1;digest:string;blocks:readonly RichTemplateBlock[]}
export interface RichTemplateFinding {blockId:string;message:string}

const collections:Record<DocumentationTemplateKind,readonly string[]>={overview:["overview.fields"],flow:["flow.pages","table.rows","flow.rows"],matrix:["matrix.rows","matrix.concepts","table.rows"],profile:["profile.rows","profile.concepts","table.rows"]};
const childBindings:Record<string,readonly string[]>={"overview.fields":["field.label","field.value"],"flow.pages":["page.stepLabel","page.pageName","page.sourcePageName","page.eventName","page.heading","page.visual.description","page.visual.caption","page.visual.sourceReference","page.rows","page.concepts","page.events"],"page.events":["event.eventName","event.heading","event.rows","event.concepts"],"page.rows":["row.property","row.concept","row.cells"],"event.rows":["row.property","row.concept","row.cells"],"table.rows":["row.concept","row.cells"],"flow.rows":["row.property","row.cells"],"matrix.rows":["row.property","row.concept","row.cells"],"profile.rows":["row.property","row.concept","row.cells"],"matrix.concepts":["concept.name","concept.rows"],"profile.concepts":["concept.name","concept.rows"],"page.concepts":["concept.name","concept.rows"],"event.concepts":["concept.name","concept.rows"],"concept.rows":["row.property","row.concept","row.cells"],"row.cells":["cell.columnKey","cell.heading","cell.value"]};
const childCollections:Record<string,readonly string[]>={"flow.pages":["page.events","page.rows","page.concepts"],"page.events":["event.rows","event.concepts"],"page.rows":["row.cells"],"event.rows":["row.cells"],"table.rows":["row.cells"],"flow.rows":["row.cells"],"matrix.rows":["row.cells"],"profile.rows":["row.cells"],"matrix.concepts":["concept.rows"],"profile.concepts":["concept.rows"],"page.concepts":["concept.rows"],"event.concepts":["concept.rows"],"concept.rows":["row.cells"]};
const itemRoot=(collection:string)=>collection.endsWith(".pages")?"page":collection.endsWith(".events")?"event":collection.endsWith(".cells")?"cell":collection.endsWith(".concepts")?"concept":collection.endsWith(".fields")?"field":"row";
const scoped=(paths:readonly string[],canonical:string,variable:string)=>paths.map(path=>path.replace(new RegExp(`^${itemRoot(canonical)}\\.`,"u"),`${variable}.`));
const rootCollectionMap=(kind:DocumentationTemplateKind)=>new Map((collections[kind]??[]).map(path=>[path,path]));
const childCollectionMap=(canonical:string,variable:string)=>new Map((childCollections[canonical]??[]).map(path=>[path.replace(new RegExp(`^${itemRoot(canonical)}\\.`,"u"),`${variable}.`),path]));

export function richTemplateHelpBindingsFor(kind:DocumentationTemplateKind):readonly string[]{
  const help=new Set(templateBindingsFor(kind)),pending=[...collections[kind]],visited=new Set<string>();
  while(pending.length){const collection=pending.shift()!;if(visited.has(collection))continue;visited.add(collection);help.add(collection);for(const binding of childBindings[collection]??[])help.add(binding);for(const nested of childCollections[collection]??[]){help.add(nested);pending.push(nested);}}
  return[...help];
}

export interface RichTemplateBlockScope {bindings:readonly string[];collections:readonly string[];childBindings:readonly string[];childCollections:readonly string[]}
export function richTemplateBlockScopes(kind:DocumentationTemplateKind,blocks:readonly RichTemplateBlock[]):Readonly<Record<string,RichTemplateBlockScope>>{const result:Record<string,RichTemplateBlockScope>={};const visit=(items:readonly RichTemplateBlock[],bindings:readonly string[],available:ReadonlyMap<string,string>)=>{for(const block of items){const repeat=block.type==="repeat"?block:undefined,canonical=repeat?available.get(repeat.items):undefined,nestedBindings=canonical&&repeat?[...bindings,...scoped(childBindings[canonical]??[],canonical,repeat.variable)]:bindings,nestedCollections=canonical&&repeat?childCollectionMap(canonical,repeat.variable):available;result[block.id]={bindings:[...bindings],collections:[...available.keys()],childBindings:[...nestedBindings],childCollections:[...nestedCollections.keys()]};if(repeat)visit(repeat.children,nestedBindings,nestedCollections);}};visit(blocks,templateBindingsFor(kind),rootCollectionMap(kind));return result;}

export function validateRichDocumentationTemplate(template:RichDocumentationTemplate):{valid:boolean;findings:RichTemplateFinding[]}{
  const findings:RichTemplateFinding[]=[],ids=new Set<string>(),root=new Set(templateBindingsFor(template.kind)),tableSources=new Set(["table",template.kind==="overview"?"overview.fields":template.kind==="flow"?"flow.rows":template.kind==="matrix"?"matrix.rows":"profile.rows"]),conceptSources=new Set(["table.concepts","matrix.concepts","profile.concepts","page.concepts","event.concepts"]),knownTypes=new Set(["heading","paragraph","divider","theme-logo","page-visual","data-table","concept-group","repeat"]);
  const report=(blockId:unknown,message:string)=>findings.push({blockId:typeof blockId==="string"&&blockId?blockId:"(unknown block)",message});
  const visit=(rawBlocks:unknown,bindings:Set<string>,availableCollections:ReadonlyMap<string,string>,rootScope:boolean)=>{
    if(!Array.isArray(rawBlocks)){report("(template)","Rich template blocks must be an ordered collection.");return;}
    for(const raw of rawBlocks){
      if(!raw||typeof raw!=="object"||Array.isArray(raw)){report("(unknown block)","Rich template blocks must be semantic block records.");continue;}const block=raw as Partial<RichTemplateBlock>&Record<string,unknown>,id=block.id;
      if(typeof id!=="string"||!id){report(id,"A rich template block needs a stable identity.");continue;}if(ids.has(id))report(id,`Duplicate block identity ${id}.`);ids.add(id);if(typeof block.type!=="string"||!knownTypes.has(block.type)){report(id,`Unsupported rich template block ${String(block.type??"")}.`);continue;}
      if(block.type==="heading"||block.type==="paragraph"){
        if(block.type==="heading"&&![1,2,3].includes(Number(block.level)))report(id,"Heading level must be 1, 2, or 3.");if(!Array.isArray(block.content)){report(id,"Text blocks need ordered text and binding content.");continue;}
        for(const rawInline of block.content){if(!rawInline||typeof rawInline!=="object"||Array.isArray(rawInline)){report(id,"Text content must contain text or binding records.");continue;}const inline=rawInline as Record<string,unknown>,hasText=typeof inline.text==="string",hasBinding=typeof inline.binding==="string";if(hasText===hasBinding)report(id,"Text content must contain exactly one text or binding value.");if(hasBinding&&!bindings.has(String(inline.binding)))report(id,`Binding ${String(inline.binding)} is outside this block scope.`);if(inline.emphasis!==undefined&&!['strong','emphasis'].includes(String(inline.emphasis)))report(id,"Text emphasis must be bold, italic, or unset.");}
      }
      if(block.type==="data-table"&&!tableSources.has(String(block.source)))report(id,`Data table ${String(block.source??"")} is outside this template kind.`);
      if(block.type==="concept-group"){const source=String(block.source??""),canonical=availableCollections.get(source),rootTableConcepts=rootScope&&source==="table.concepts";if(!rootTableConcepts&&(!canonical||!conceptSources.has(canonical)))report(id,`Concept collection ${source} is outside this block scope.`);}
      if(block.type==="page-visual"){const source=String(block.source??"");if(!bindings.has(`${source}.description`))report(id,`Page visual ${source} is outside this block scope.`);}
      if(block.type==="repeat"){
        const canonical=availableCollections.get(String(block.items));if(!canonical)report(id,`Collection ${String(block.items)} is outside this block scope.`);if(typeof block.variable!=="string"||!/^[a-z][a-zA-Z0-9]*$/u.test(block.variable))report(id,"Repeat item name must be a safe binding name.");const variable=typeof block.variable==="string"&&block.variable?block.variable:"item",nestedBindings=canonical?new Set([...bindings,...scoped(childBindings[canonical]??[],canonical,variable)]):new Set(bindings),nestedCollections=canonical?childCollectionMap(canonical,variable):new Map<string,string>();visit(block.children,nestedBindings,nestedCollections,false);
      }
    }
  };
  if(!Object.hasOwn(collections,template.kind))report("(template)",`Unsupported documentation kind ${String(template.kind)}.`);else visit(template.blocks,root,rootCollectionMap(template.kind),true);return{valid:findings.length===0,findings};
}

export function builtInRichTemplate(kind:DocumentationTemplateKind,id:string,name:string):RichDocumentationTemplate{
  const blocks:RichTemplateBlock[]=[{id:`${id}:heading`,type:"heading",level:1,content:[{binding:"section.name"}]},{id:`${id}:table`,type:"data-table",source:kind==="overview"?"overview.fields":kind==="flow"?"flow.rows":kind==="matrix"?"matrix.rows":"profile.rows"}];
  return{id,name,format:"rich",kind,contractVersion:1,digest:templateDigest("rich",blocks),blocks};
}

const htmlEscape=(value:unknown)=>String(value??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;").replaceAll("\n","<br>");
const scalar=(value:TemplateContextValue)=>value==null?"":typeof value==="object"?JSON.stringify(value):String(value);
const inlineValue=(item:RichInline,context:TemplateContextObject)=>"text" in item?item.text:scalar(templateValueAt(context,item.binding));
const inlineText=(items:readonly RichInline[],context:TemplateContextObject)=>items.map(item=>inlineValue(item,context)).join("");
const inlineHtml=(items:readonly RichInline[],context:TemplateContextObject)=>items.map(item=>{const value=htmlEscape(inlineValue(item,context));return item.emphasis==="strong"?`<strong>${value}</strong>`:item.emphasis==="emphasis"?`<em>${value}</em>`:value;}).join("");
const tableRows=(value:TemplateContextValue):{headings:string[];rows:string[][]}=>{if(!value||typeof value!=="object")return{headings:[],rows:[]};if(Array.isArray(value))return{headings:[],rows:value.map(item=>[scalar(item)])};const table=value as TemplateContextObject,columns=Array.isArray(table.columns)?table.columns.map(column=>scalar((column as TemplateContextObject).heading)):[],records=Array.isArray(table.rows)?table.rows as readonly TemplateContextObject[]:[],fields=records.length>0&&records.every(record=>record.label!==undefined),properties=records.some(record=>record.property!==undefined),firstCells=records.length>0&&Array.isArray(records[0]!.cells)?records[0]!.cells as readonly TemplateContextObject[]:[],propertyInCells=properties&&firstCells[0]?.columnKey==="property",headings=fields?["Field","Value"]:propertyInCells?firstCells.map(cell=>scalar(cell.heading)):properties?["Property",...columns]:columns,rows=records.map(record=>{if(fields)return[scalar(record.label),scalar(record.value)];const cellRecords=Array.isArray(record.cells)?record.cells as readonly TemplateContextObject[]:[],cells=cellRecords.map(cell=>scalar(cell.value)),ownsProperty=record.property!==undefined&&cellRecords[0]?.columnKey==="property";return properties&&!ownsProperty?[scalar(record.property),...cells]:cells;});return{headings,rows};};

export function renderRichDocumentationTemplate(template:RichDocumentationTemplate,context:TemplateContextObject):{html:string;plain:string}{
  const validation=validateRichDocumentationTemplate(template);if(!validation.valid)throw new Error(validation.findings.map(({blockId,message})=>`${blockId}: ${message}`).join("\n"));
  const render=(blocks:readonly RichTemplateBlock[],scope:TemplateContextObject):{html:string;plain:string[]}=>{let html="";const plain:string[]=[];for(const block of blocks){if(block.type==="heading"||block.type==="paragraph"){const value=inlineText(block.content,scope);html+=block.type==="heading"?`<h${block.level}>${inlineHtml(block.content,scope)}</h${block.level}>`:`<p>${inlineHtml(block.content,scope)}</p>`;plain.push(value);continue;}if(block.type==="divider"){html+="<hr>";continue;}if(block.type==="theme-logo"){const logo=scalar(templateValueAt(scope,"theme.logo"));if(logo)html+=`<img src="${htmlEscape(logo)}" alt="">`;continue;}if(block.type==="page-visual"){const value=templateValueAt(scope,block.source);if(!value||typeof value!=="object"||Array.isArray(value))continue;const visual=value as TemplateContextObject,image=scalar(visual.image),description=scalar(visual.description),caption=scalar(visual.caption),sourceReference=scalar(visual.sourceReference);if(!image)continue;html+=`<figure data-page-visual="true"><img src="${htmlEscape(image)}" alt="${htmlEscape(description)}">${caption?`<figcaption>${htmlEscape(caption)}</figcaption>`:""}${sourceReference?`<p data-visual-source="true">${htmlEscape(sourceReference)}</p>`:""}</figure>`;plain.push(description,...(caption?[caption]:[]),...(sourceReference?[sourceReference]:[]));continue;}if(block.type==="repeat"){const items=templateValueAt(scope,block.items);if(Array.isArray(items))for(const item of items){const child=render(block.children,{...scope,[block.variable]:item as TemplateContextValue,[itemRoot(block.items)]:item as TemplateContextValue});html+=child.html;plain.push(...child.plain);}continue;}if(block.type==="data-table"){const value=block.source==="table"?templateValueAt(scope,"table"):{columns:templateValueAt(scope,"table.columns"),rows:templateValueAt(scope,block.source)},table=tableRows(value),head=table.headings.length?`<thead><tr>${table.headings.map(item=>`<th>${htmlEscape(item)}</th>`).join("")}</tr></thead>`:"",body=table.rows.map(row=>`<tr>${row.map(item=>`<td>${htmlEscape(item)}</td>`).join("")}</tr>`).join("");html+=`<table>${head}<tbody>${body}</tbody></table>`;if(table.headings.length)plain.push(table.headings.join("\t"));plain.push(...table.rows.map(row=>row.join("\t")));continue;}if(block.type==="concept-group"){const concepts=templateValueAt(scope,block.source),columns=templateValueAt(scope,"table.columns");if(Array.isArray(concepts))for(const value of concepts){if(!value||typeof value!=="object"||Array.isArray(value))continue;const concept=value as TemplateContextObject,rows=concept.rows;if(!Array.isArray(rows)||rows.length===0)continue;const name=scalar(concept.name),table=tableRows({columns,rows}),body=table.rows.map(row=>`<tr>${row.map(item=>`<td>${htmlEscape(item)}</td>`).join("")}</tr>`).join("");html+=`<section data-concept-group="${htmlEscape(name)}"><h3>${htmlEscape(name)}</h3><table><tbody>${body}</tbody></table></section>`;plain.push(name,...table.rows.map(row=>row.join("\t")));}continue;}}
    return{html,plain};};
  const output=render(template.blocks,context);return{html:`<section data-documentation-template="rich">${output.html}</section>`,plain:output.plain.join("\n")};
}
